                totalItemsCount = count,
                isLoadingMoreRecommendations = false,
                prefetchThreshold = resolvePortraitRecommendationPrefetchThreshold(onlyVerticalRecommendations)
            )
        ) latestLoadMoreRecommendations()
    }
}

